{ ILogService } from './services/logService';\nimport { isDevcontainerSessionOutofSync } from './services/gitpodApi';\nimport { showEnvironmentDetailsViewWithConfig, type IWindowActions, type IWindowStateManager, type WindowType } from './windowStateManager';\n\nexport class SSHWindowStateManager implements IWindowStateManager {\n    constructor(\n        private windowActions: IWindowActions,\n        private readonly windowType: WindowType,\n        private windowContainerSession?: string,\n    ) { }\n\n    onEnvironmentContainerUpdated(environmentRef: EnvironmentRef, environment: Environment, isNewConnection: boolean) {\n        this.doOnEnvironmentContainerUpdated(environmentRef, environment, isNewConnection);\n\n        this.windowActions.showRemoteResolverProgress();\n    }\n\n    private doOnEnvironmentContainerUpdated(environmentRef: EnvironmentRef, environment: Environment, isNewConnection: boolean) {\n        const environmentStatus = environment.status!;\n        const environmentPhase = environmentStatus.phase;\n        const containerPhase = environmentStatus.devcontainer?.phase;\n        const isEnvironmentWindow = this.windowType === 'devcontainer' && !isNewConnection;\n\n        if (isEnvironmentWindow) {\n            if (this.windowContainerSession === undefined && environmentStatus.devcontainer?.session !== undefined) {\n                this.windowContainerSession = environmentStatus.devcontainer.session;\n            }\n            if (this.windowContainerSession !== environmentStatus.devcontainer?.session) {\n                this.windowActions.reloadWindow();\n            }\n        }\n\n        if (environmentPhase === EnvironmentPhase.CREATING || environmentPhase === EnvironmentPhase.STARTING) {\n            if (isEnvironmentWindow) {\n                this.windowActions.showProgress('initial');\n            } else {\n                // progress\n            }\n            return;\n        }\n        if (environmentPhase === EnvironmentPhase.RUNNING) {\n            if (isDevcontainerSessionOutofSync(environment)) {\n                if (isEnvironmentWindow) {\n                    this.windowActions.showProgress('rebuild');\n                }\n            } else {\n                if (isEnvironmentWindow) {\n                    this.windowActions.hideProgress();\n                }\n                if (containerPhase === EnvironmentStatus_DevContainer_Phase.RUNNING) {\n                    if (isNewConnection) {\n                        this.windowActions.redirectToContainer(environmentStatus.environmentUrls!.ssh!.url, environmentStatus.devcontainer!.remoteWorkspaceFolder, environmentRef, isNewConnection);\n                    }\n                    return;\n                }\n                if (containerPhase === EnvironmentStatus_DevContainer_Phase.STOPPED) {\n                    if (isNewConnection) {\n                        this.windowActions.redirectToContainer(environmentStatus.environmentUrls!.ssh!.url, environmentStatus.devcontainer!.remoteWorkspaceFolder, environmentRef, isNewConnection);\n                    } else if (isEnvironmentWindow) {\n                        this.windowActions.showError('stopped');\n                    }\n                    return;\n                }\n                if (containerPhase === EnvironmentStatus_DevContainer_Phase.FAILED) {\n                    if (isNewConnection) {\n                        this.windowActions.redirectToContainer(environmentStatus.environmentUrls!.ssh!.url, environmentStatus.devcontainer!.remoteWorkspaceFolder, environmentRef, isNewConnection);\n                    } else if (isEnvironmentWindow) {\n                        this.windowActions.showError('failed');\n                    }\n                    return;\n                }\n            }\n            return;\n        }\n        if (environmentPhase === EnvironmentPhase.UPDATING) {\n            if (containerPhase === EnvironmentStatus_DevContainer_Phase.CREATING) {\n                if (isEnvironmentWindow) {\n                    this.windowActions.showProgress('rebuild');\n                }\n            }\n            return;\n        }\n        if (environmentPhase === EnvironmentPhase.STOPPING) {\n            if (isEnvironmentWindow) {\n                this.windowActions.showProgress('stopping', true, true);\n                this.windowActions.closeWindow();\n            }\n            return;\n        }\n        if (environmentPhase === EnvironmentPhase.STOPPED) {\n            if (isEnvironmentWindow) {\n                this.windowActions.showProgress('stopped', true, true);\n                this.windowActions.closeWindow();\n            }\n            return;\n        }\n        if (environmentPhase === EnvironmentPhase.DELETING) {\n            if (isEnvironmentWindow) {\n                this.windowActions.showProgress('deleting', true, true);\n                this.windowActions.closeWindow();\n            }\n            return;\n        }\n        if (environmentPhase === EnvironmentPhase.DELETED) {\n            if (isEnvironmentWindow) {\n                this.windowActions.showProgress('deleted', true, true);\n                this.windowActions.closeWindow();\n            }\n            return;\n        }\n    }\n}\n\nexport class DesktopWindowActions implements IWindowActions {\n    private pendingProgress: DeferredPromise<void> | undefined;\n\n    constructor(\n        private readonly context: vscode.ExtensionContext,\n        private readonly remoteConnectionInfo: RemoteConnectionInfo | undefined,\n        private readonly logService: ILogService,\n    ) { }\n\n    async redirectToContainer(sshUrl: string, remoteWorkspaceFolder: string, environmentRef: EnvironmentRef, isNewConnection: boolean): Promise<void> {\n        const remoteUri = computeSSHRemoteUri(environmentRef.environmentId, sshUrl, remoteWorkspaceFolder);\n        await storeEnvironmentRef(this.context, remoteUri, { ...environmentRef, connectionMode: 'remote-ssh' });\n\n        let params: { forceNewWindow?: boolean; forceReuseWindow?: boolean };\n        if (isNewConnection && environmentRef.environmentId !== this.remoteConnectionInfo?.environmentRef.environmentId) {\n            const forceNewWindow = this.context.extensionMode === vscode.ExtensionMode.Production\n                && (!!vscode.env.remoteName\n                    || !!vscode.workspace.workspaceFile\n                    || !!vscode.workspace.workspaceFolders\n                    || !!vscode.window.visibleTextEditors.length\n                    || !!vscode.window.visibleNotebookEditors.length);\n            params = { forceNewWindow };\n        } else {\n            params = { forceReuseWindow: true };\n        }\n\n        await vscode.commands.executeCommand('vscode.openFolder', remoteUri, params);\n    }\n\n    showError(reason: 'failed' | 'stopped'): void {\n        if (!this.remoteConnectionInfo) {\n            return;\n        }\n        let msg = reason === 'failed' ? 'Container failed to start.' : 'Container stopped unexpectedly.';\n        msg += ' Run \\'Rebuild Container\\' command to try again.';\n        vscode.window.showErrorMessage(msg, { modal: true });\n        vscode.commands.executeCommand('gitpod-flex.showEnvironmentDetails');\n    }\n\n    async closeWindow(): Promise<void> {\n        await vscode.commands.executeCommand('workbench.action.remote.close');\n    }\n\n    async reloadWindow(): Promise<void> {\n        await vscode.commands.executeCommand('workbench.action.reloadWindow');\n    }\n\n    showProgress(kind: 'initial' | 'rebuild' | 'stopping' | 'stopped' | 'deleting' | 'deleted', showEnvironmentDetails: boolean = true, override: boolean = false): void {\n        if (this.pendingProgress && override) {\n            this.hideProgress();\n        }\n        if (!this.pendingProgress) {\n            this.pendingProgress = this.createProgress(kind);\n            if (showEnvironmentDetails) {\n                showEnvironmentDetailsViewWithConfig(this.context, this.remoteConnectionInfo, true);\n            }\n        }\n    }\n\n    showRemoteResolverProgress() {\n        // Hack: vscode.env.shell is empty until the resolver extension resolves the remote host completely\n        // Shows progress bar while devcontainer/ssh extension is resolving the remote\n        if (!vscode.env.shell && !this.pendingProgress) {\n            this.showProgress('initial', false);\n            const toDispose = vscode.env.onDidChangeShell(() => {\n                this.hideProgress();\n                toDispose.dispose();\n            });\n        }\n    }\n\n    private createProgress(kind: 'initial' | 'rebuild' | 'stopping' | 'stopped' | 'deleting' | 'deleted') {\n        if (!this.remoteConnectionInfo) {\n            return undefined;\n        }\n        const environmentRef = this.remoteConnectionInfo.environmentRef;\n        const pendingProgress = new DeferredPromise<void>();\n        const showDetailsCommandUri = vscode.Uri.parse(`command:gitpod-flex.showEnvironmentDetails?${encodeURIComponent(JSON.stringify([environmentRef]))}`);\n        const showLogsCommandUri = vscode.Uri.parse(`command:gitpod-flex.showExtensionLogs`);\n        let title: string;\n        if (kind === 'initial') {\n            title = 'Opening environment';\n        } else if (kind === 'rebuild') {\n            title = 'Rebuilding container';\n        } else if (kind === 'stopping' || kind === 'stopped') {\n            title = `Environment is ${kind}, restart the environment to connect`;\n        } else { // if (kind === 'deleting' || 'deleted')\n            title = `Environment is ${kind}, close the current window`;\n        }\n\n        vscode.window.withProgress({\n            location: vscode.ProgressLocation.Notification,\n            title: `${title} ([manage environment](${showDetailsCommandUri}), [logs](${showLogsCommandUri}))`,\n        }, progress => {\n            if (kind === 'initial') {\n                const networkCheckTimeout = setTimeout(() => {\n                    this.logService.warn(`Opening environment '${environmentRef.environmentId}' is taking longer than expected. Check your network, close and reopen the window if needed.`);\n                    progress.report({ message: 'Taking longer than expected. Check your network, close and reopen the window if needed.' });\n                }, 5 * 1000);\n                pendingProgress.p.finally(() => clearTimeout(networkCheckTimeout));\n            }\n            return pendingProgress.p;\n        });\n        return pendingProgress;\n    }\n\n    hideProgress(): void {\n        this.pendingProgress?.complete();\n        this.pendingProgress = undefined;\n    }\n\n    private timeoutPromise1: Promise<void> | undefined;\n    async promptRebuild(): Promise<void> {\n        if (!this.remoteConnectionInfo) {\n            return;\n        }\n        if (this.pendingProgress) {\n            await this.pendingProgress.p;\n        }\n\n        if (this.timeoutPromise1) {\n            return;\n        }\n\n        // Info notifications are hidden after 15 seconds, see notificationsToasts.ts in vscode\n        this.timeoutPromise1 = timeout(16000).then(() => this.timeoutPromise1 = undefined);\n\n        const yesRebuild = 'Rebuild Now';\n        vscode.window.showInformationMessage(`We've noticed a change to the dev container configuration. Rebuild the container to apply them now.`, yesRebuild)\n            .then(action => {\n                if (action === yesRebuild) {\n                    vscode.commands.executeCommand('gitpod-flex.rebuildContainer');\n                }\n            });\n    }\n\n    private timeoutPromise2: Promise<void> | undefined;\n    async promptReloadAutomationsFile(): Promise<void> {\n        if (!this.remoteConnectionInfo) {\n            return;\n        }\n        if (this.pendingProgress) {\n            await this.pendingProgress.p;\n        }\n\n        if (this.timeoutPromise2) {\n            return;\n        }\n\n        // Info notifications are hidden after 15 seconds, see notificationsToasts.ts in vscode\n        this.timeoutPromise2 = timeout(16000).then(() => this.timeoutPromise2 = undefined);\n\n        const yesApply = 'Apply';\n        vscode.window.showInformationMessage(`We've noticed a change to the Automations file. Do you want to apply the changes now.`, yesApply)\n            .then(action => {\n                if (action === yesApply) {\n                    vscode.commands.executeCommand('gitpod-flex.applyAutomationsFileChanges');\n                }\n            });\n    }\n}\n","'use strict';\n\nvar stringifyNumber = require('../../stringify/stringifyNumber.js');\n\n/** Internal types handle bigint as number, because TS can't figure it out. */\nfunction parseSexagesimal(str, asBigInt) {\n    const sign = str[0];\n    const parts = sign === '-' || sign === '+' ? str.substring(1) : str;\n    const num = (n) => asBigInt ? BigInt(n) : Number(n);\n    const res = parts\n        .replace(/_/g, '')\n        .split(':')\n        .reduce((res, p) => res * num(60) + num(p), num(0));\n    return (sign === '-' ? num(-1) * res : res);\n}\n/**\n * hhhh:mm:ss.sss\n *\n * Internal types handle bigint as number, because TS can't figure it out.\n */\nfunction stringifySexagesimal(node) {\n    let { value } = node;\n    let num = (n) => n;\n    if (typeof value === 'bigint')\n        num = n => BigInt(n);\n    else if (isNaN(value) || !isFinite(value))\n        return stringifyNumber.stringifyNumber(node);\n    let sign = '';\n    if (value < 0) {\n        sign = '-';\n        value *= num(-1);\n    }\n    const _60 = num(60);\n    const parts = [value % _60]; // seconds, including ms\n    if (value < 60) {\n        parts.unshift(0); // at least one : is required\n    }\n    else {\n        value = (value - parts[0]) / _60;\n        parts.unshift(value % _60); // minutes\n        if (value >= 60) {\n            value = (value - parts[0]) / _60;\n            parts.unshift(value); // hou