shPath || 'ssh';\n    }\n\n    private execCommand(command: string, args: string[] = [], options?: cp.SpawnOptions) {\n        const startTime = Date.now();\n        const id = this.commandSeq++;\n        this.logger.trace('ssh', id, command, ...(args || []));\n\n        let abortController: AbortController | undefined;\n        if (options?.timeout && options.timeout > 0) {\n            abortController = new AbortController();\n            setTimeout(() => abortController?.abort(), options.timeout);\n        }\n        const opts: cp.SpawnOptions = {\n            ...options,\n            signal: abortController?.signal,\n            windowsVerbatimArguments: true,\n        };\n        const childProcess = cp.spawn(command, args, opts);\n        const stdoutDataArr: string[] = [];\n        const stderrDataArr: string[] = [];\n        childProcess.stdout?.on('data', data => {\n            stdoutDataArr.push(data.toString());\n        });\n        childProcess.stderr?.on('data', data => {\n            stderrDataArr.push(data.toString());\n        });\n        const completed = new Promise<{ code: number }>((resolve, reject) => {\n            childProcess.on('error', err => {\n                if (err.name === 'AbortError') {\n                    err = new SSHCommandTimeoutError(`${command} ${(args || []).join(' ')}`, stdoutDataArr.join(''), stderrDataArr.join(''));\n                }\n\n                const duration = Date.now() - startTime;\n                this.logger.trace('ssh', id, duration, 'failure', err);\n                reject(err);\n            });\n            childProcess.on('close', code => {\n                code = code ?? 256;\n\n                const duration = Date.now() - startTime;\n                this.logger.trace('ssh', id, duration, 'success', code);\n                resolve({ code });\n            });\n        });\n\n        return {\n            get stdout() {\n                return stdoutDataArr.join('');\n            },\n            get st