ttps://releases.gitpod.io';\nconst NEW_BASE_URL = 'https://app.gitpod.io/releases';\n\n/**\n * Replaces the base URL in a release URL string.\n * Always rewrites to use app.gitpod.io/releases first, with fallback to releases.gitpod.io.\n * Similar to mutateReleaseURLs in backend/api/runner_interaction.go\n *\n * @param url - The URL to transform\n * @returns The URL with the new base\n *\n * @internal Exported for testing\n */\nexport function replaceBaseUrl(url: string): string {\n    return url.replace(OLD_BASE_URL, NEW_BASE_URL);\n}\n\nexport interface IRemoteService {\n    setupSSHProxy: (environmentId: string, userId: string, orgId: string, sshUrl: string) => Promise<{ host: string; sshKeyFilePath: string }>;\n    startLocalSSHServiceServer: () => Promise<void>;\n}\n\nexport class RemoteService extends Disposable implements IRemoteService {\n    private nativeSSH: NativeSSH;\n    private extensionServiceServer: SshProxyServiceServer | undefined;\n    private gitpodCLIPath: string;\n    private gitpodCLIConfigFolder: string;\n\n    constructor(\n        private readonly context: vscode.ExtensionContext,\n        private readonly hostService: IHostService,\n        private readonly sessionService: ISessionService,\n        private readonly logService: ILogService,\n        private readonly telemetryService: VSCodeTelemetryService,\n        private readonly featureFlagService: IFeatureFlagService,\n    ) {\n        super();\n        this.nativeSSH = new NativeSSH(vscode.workspace.getConfiguration('remote.SSH').get<string>('path'), logService);\n        this.gitpodCLIPath = vscode.Uri.joinPath(this.context.globalStorageUri, `gitpod-cli${isWindows ? '.exe' : ''}`).fsPath;\n        this.gitpodCLIConfigFolder = vscode.Uri.joinPath(this.context.globalStorageUri, 'gitpod-cli-config').fsPath;\n    }\n\n    async startLocalSSHServiceServer() {\n        this.logService.info('Starting SSH proxy service server');\n        if (!this.extensionServiceServer) {\n            this