          const exists = await vscode.workspace.fs.stat(this.configFile).then(() => true, () => false);\n            if (!exists) {\n                await vscode.workspace.fs.writeFile(this.configFile, new TextEncoder().encode(automationsFileTemplate));\n            }\n\n            await vscode.window.showTextDocument(this.configFile, { preview: false });\n        } catch (e) {\n            this.logService.error(`Failed to open Automations Configuration`);\n            this.logService.error(e);\n        }\n    }\n}\n\nexport class AddTaskAutomationCommand implements Command {\n    readonly id = 'gitpod-flex.addTaskAutomation';\n\n    constructor(\n        private configFile: vscode.Uri,\n        private readonly logService: ILogService,\n    ) { }\n\n    async execute() {\n        try {\n            const exists = await vscode.workspace.fs.stat(this.configFile).then(() => true, () => false);\n            if (!exists) {\n                await vscode.workspace.fs.writeFile(this.configFile, new TextEncoder().encode(automationsFileTemplate));\n                await vscode.window.showTextDocument(this.configFile, { preview: false });\n            } else {\n                const textEditor = await vscode.window.showTextDocument(this.configFile, { preview: false });\n                let automationsYaml = textEditor.document.getText();\n                let automationsJson = parseYAMLDocument(automationsYaml);\n                const automationsTemplateJson = parseYAML(automationsFileTemplate);\n                let edit = false;\n                if (!automationsJson.has('tasks')) {\n                    automationsJson.add({ key: 'tasks', value: { hello: automationsTemplateJson.tasks['hello'] } });\n                    edit = true;\n                } else if (!automationsJson.hasIn(['tasks', 'hello'])) {\n                    automationsJson.addIn(['tasks'], { key: 'hello', value: automationsTemplateJson.tasks['hello'] });\n                    edit = true;\n                }\n