withLock } from 'gitpod-shared/out/common/lock';\nimport SSHConfiguration from './ssh/sshConfig';\nimport { WrapError } from 'gitpod-shared/out/common/errors';\nimport { EnvironmentPhase } from 'gitpod-next-api/lib/gitpod/v1/environment_pb';\nimport { Code, ConnectError } from '@connectrpc/connect';\nimport { SSH_PUBLIC_KEY_NAME, ENVIRONMENT_KEY, EnvironmentRef } from './remote';\nimport { SSHDestination } from './sshDestination';\nimport { ISessionService } from './services/sessionService';\nimport type { IGitpodAPI } from './services/gitpodApi';\nimport { GitpodPublicApi } from './gitpodPublicApi';\n\nconst LOCK_FOLDER = 'sshcleanup';\nconst LAST_CLEANUP_FILE = 'lastSshConfigCleanup.txt';\nconst CLEANUP_TIME_SCHEDULE = 1000 * 60 * 60 * 24; /* one day */\n\nexport abstract class AbstractConfigCleaner {\n    protected abstract isHostDeleted(host: string): Promise<boolean>;\n\n    async cleanConfig(sshConfig: SSHConfiguration): Promise<{ updatedSshConfig: SSHConfiguration; sshKeysToDelete: string[]; deletedHosts: string[] }> {\n        const allHosts = sshConfig.getAllConfiguredHosts();\n        const sshKeysToDelete: string[] = [];\n        const deletedHosts: string[] = [];\n        for (const host of allHosts) {\n            if (await this.isHostDeleted(host)) {\n                const hostConfig = sshConfig.getHostConfiguration(host);\n                const sshKeyPath = hostConfig['IdentityFile'] as string[] | undefined;\n                if (sshKeyPath && !sshKeyPath.some(s => s.endsWith(SSH_PUBLIC_KEY_NAME))) {\n                    sshKeysToDelete.push(...sshKeyPath);\n                }\n                sshConfig.removeHostConfiguration(host);\n                deletedHosts.push(host);\n            }\n        }\n        return { updatedSshConfig: sshConfig, sshKeysToDelete, deletedHosts };\n    }\n}\n\nexport class SSHConfigCleaner extends AbstractConfigCleaner {\n    private apiMap = new Map<string, IGitpodAPI>();\n\n    constructor(\n        private readonly context: vscode.ExtensionContext,\n        private readonly sessionService: ISessionService,\n        private readonly logService: ILogService,\n    ) {\n        super();\n    }\n\n    async run() {\n        try {\n            const lockUri = vscode.Uri.joinPath(this.context.globalStorageUri, LOCK_FOLDER);\n            await withLock(lockUri.fsPath, this.doRun.bind(this));\n        } catch (e) {\n            this.logService.error('Failed to clean ssh config', e);\n        }\n    }\n\n    private async doRun() {\n        const fileUri = vscode.Uri.joinPath(this.context.globalStorageUri, LAST_CLEANUP_FILE);\n        let lastDate: Date;\n        try {\n            const fileContentBuffer = await vscode.workspace.fs.readFile(fileUri);\n            const fileContent = new TextDecoder().decode(fileContentBuffer);\n            lastDate = new Date(parseInt(fileContent, 10));\n        } catch (e) {\n            if (e instanceof vscode.FileSystemError && e.code === 'FileNotFound') {\n                lastDate = new Date(0);\n            } else {\n                throw e;\n            }\n        }\n\n        const timeDiff = Date.now() - lastDate.getTime();\n        if (timeDiff >= CLEANUP_TIME_SCHEDULE) {\n            await this.doCleanup();\n        }\n\n        const content = `${Date.now()}`;\n        await vscode.workspace.fs.writeFile(fileUri, new TextEncoder().encode(content));\n    }\n\n    private async doCleanup() {\n        const gitpodConfig = await SSHConfiguration.loadGitpodSSHConfig();\n\n        const { updatedSshConfig, sshKeysToDelete, deletedHosts } = await this.cleanConfig(gitpodConfig);\n\n        if (deletedHosts.length === 0) {\n            return;\n        }\n\n        const result = await Promise.allSettled(sshKeysToDelete.map(async filePath => {\n            await vscode.workspace.fs.delete(vscode.Uri.file(filePath));\n            await vscode.workspace.fs.delete(vscode.Uri.file(filePath + '.pub'));\n        }));\n        result.forEach((value, i) => {\n 