onst isCursor = vscode.env.appName.includes('Cursor') ? 1 : 0;\n        const proxyAssetBaseUrl = getProxyAssetBaseUrl(s3AssetBaseUrl);\n        return `# use busybox to remove a dependency on image\nMKDIR=$(command -v mkdir || echo \"/usr/local/gitpod/shared/busybox mkdir\")\nRM=$(command -v rm || echo \"/usr/local/gitpod/shared/busybox rm\")\nUNAME=$(command -v uname || echo \"/usr/local/gitpod/shared/busybox uname\")\nCHMOD=$(command -v chmod || echo \"/usr/local/gitpod/shared/busybox chmod\")\n\nARCH=\"amd64\"\nif [ \"$($UNAME -m)\" = \"aarch64\" ] || [ \"$($UNAME -m)\" = \"arm64\" ]; then\n    ARCH=\"arm64\"\nfi\n\n# Test connectivity to original URL with 1 second timeout, fallback to proxy if it fails\nORIGINAL_BASE_URL=\"${s3AssetBaseUrl}\"\nPROXY_BASE_URL=\"${proxyAssetBaseUrl}\"\nTEST_URL=\"$ORIGINAL_BASE_URL/vscode-agent-$ARCH\"\necho \"Testing connectivity to $TEST_URL\"\n\n# Try wget first, then curl for connectivity test\nif [ -n $(which wget) ]; then\n    if wget --method=HEAD --timeout=1 --tries=1 --no-verbose \"$TEST_URL\" > /dev/null 2>&1; then\n        echo \"Using original asset URL: $ORIGINAL_BASE_URL\"\n        AGENT_BASE_URL=\"$ORIGINAL_BASE_URL\"\n    else\n        echo \"Original URL not accessible, using proxy: $PROXY_BASE_URL\"\n        AGENT_BASE_URL=\"$PROXY_BASE_URL\"\n    fi\nelif [ -n $(which curl) ]; then\n    if curl --head --connect-timeout 1 --location --show-error --silent \"$TEST_URL\" > /dev/null 2>&1; then\n        echo \"Using original asset URL: $ORIGINAL_BASE_URL\"\n        AGENT_BASE_URL=\"$ORIGINAL_BASE_URL\"\n    else\n        echo \"Original URL not accessible, using proxy: $PROXY_BASE_URL\"\n        AGENT_BASE_URL=\"$PROXY_BASE_URL\"\n    fi\nelse\n    echo \"No wget or curl available for connectivity test, using proxy: $PROXY_BASE_URL\"\n    AGENT_BASE_URL=\"$PROXY_BASE_URL\"\nfi\n\nAGENT_DOWNLOAD_URL=\"$AGENT_BASE_URL/vscode-agent-$ARCH\"\nAGENT_INSTALL_DIR=\"/usr/local/gitpod/shared/vscode/${extensionVersion}\"\nAGEN